{"explanation":"**Break-even analysis with linear equations**

Each plan is a linear equation:
- **Plan A:** C_A = 20 + 0.10m
- **Plan B:** C_B = 35 + 0.05m

Set them equal to find when they cost the same:

20 + 0.10m = 35 + 0.05m
0.05m = 15
**m = 300 minutes**, at a cost of **$50**.

Interpretation: Plan A starts cheaper ($20 < $35), but its steeper per-minute rate ($0.10 > $0.05) means Plan B catches up. Before 300 minutes Plan A is cheaper; after 300 minutes Plan B wins. The slider below lets you drag the number of minutes and watch both running cost totals — the intersection point is highlighted at m = 300.","manimCode":"// Phone plan break-even analysis
// Plan A: 20 + 0.10m   |   Plan B: 35 + 0.05m
// Intersection at m = 300 min, cost = $50

const axes = new Axes({
  xRange: [0, 600, 100],
  yRange: [0, 90, 15],
  xLength: 10,
  yLength: 6,
  tips: false
});
axes.moveTo([-0.5, -0.3, 0]);

const labels = axes.getAxisLabels();

// Curve titles / legend
const title = new Text({ text: 'When do the phone plans cost the same?', color: WHITE, fontSize: 30 });
title.moveTo([0, 3.3, 0]);

const legendA = new MathTex({ latex: '\\text{Plan A: } C = 20 + 0.10m', color: BLUE });
await legendA.waitForRender();
const legendB = new MathTex({ latex: '\\text{Plan B: } C = 35 + 0.05m', color: RED });
await legendB.waitForRender();
const legendGroup = new VGroup(legendA, legendB);
legendGroup.arrange(DOWN, 0.2);
legendGroup.toCorner(UR);
legendGroup.shift(scaleVec(0.35, LEFT));

// The two cost lines
const costA = m => 20 + 0.10 * m;
const costB = m => 35 + 0.05 * m;

const lineA = axes.plot(costA, { color: BLUE, strokeWidth: 4 });
const lineB = axes.plot(costB, { color: RED, strokeWidth: 4 });

// Break-even point at m = 300
const breakDot = new Dot({ point: axes.c2p(300, 50), color: YELLOW, radius: 0.13 });
const breakLabel = new MathTex({ latex: '(300,\ $50)', color: YELLOW });
await breakLabel.waitForRender();
breakLabel.nextTo(breakDot, UR);
breakLabel.shift(scaleVec(0.25, DOWN));

// Dashed guide lines to the intersection
const guideV = new Polygon({ vertices: [axes.c2p(300, 0), axes.c2p(300, 50)], color: YELLOW_D });
guideV.setStrokeWidth(2).setFillOpacity(0);
guideV.setOpacity(0.6);
const guideH = new Polygon({ vertices: [axes.c2p(0, 50), axes.c2p(300, 50)], color: YELLOW_D });
guideH.setStrokeWidth(2).setFillOpacity(0);
guideH.setOpacity(0.6);

await scene.play(new Write(title));
await scene.play(new Create(lineA), new Create(lineB));
await scene.play(new AnimationGroup([new FadeIn(legendA), new FadeIn(legendB)]));
await scene.play(new AnimationGroup([
  new Create(guideV), new Create(guideH),
  new FadeIn(breakDot), new Write(breakLabel)
]));

// Interactive part: slider controls the number of minutes
let minutes = 100;

const dotA = new Dot({ point: axes.c2p(minutes, costA(minutes)), color: BLUE, radius: 0.1 });
const dotB = new Dot({ point: axes.c2p(minutes, costB(minutes)), color: RED, radius: 0.1 });

const stemA = new Polygon({ vertices: [axes.c2p(minutes, 0), axes.c2p(minutes, costA(minutes))], color: BLUE });
stemA.setStrokeWidth(2).setFillOpacity(0);
stemA.setOpacity(0.35);
const stemB = new Polygon({ vertices: [axes.c2p(minutes, 0), axes.c2p(minutes, costB(minutes))], color: RED });
stemB.setStrokeWidth(2).setFillOpacity(0);
stemB.setOpacity(0.35);

let costText = new MathTex({
  latex: 'm = 100 \\text{ min} \\quad C_A = \\$30.00 \\quad C_B = \\$40.00',
  color: WHITE, fontSize: 34
});
await costText.waitForRender();
costText.moveTo([0, -3.4, 0]);

scene.add(dotA, dotB, stemA, stemB, costText);

function updateReadout() {
  const ca = costA(minutes);
  const cb = costB(minutes);
  const pos = costText.getCenter();
  scene.remove(costText);
  const diff = ca - cb;
  const verdict = diff < -0.005 ? '\\\\text{Plan A is cheaper}'
    : diff > 0.005 ? '\\\\text{Plan B is cheaper}'
    : '\\\\text{Equal!}';
  const vColor = diff < -0.005 ? BLUE : (diff > 0.005 ? RED : YELLOW);
  costText = new MathTex({
    latex: `m = ${Math.round(minutes)} \\text{ min} \\qquad C_A = \\$${ca.toFixed(2)} \\qquad C_B = \\$${cb.toFixed(2)}`,
    color: WHITE, fontSize: 32
  });
  const verdictTex = new MathTex({ latex: verdict, color: vColor, fontSize: 32 });
  await verdictTex.waitForRender();
  const row = new VGroup(costText, verdictTex);
  await costText.waitForRender();
  row.arrange(RIGHT, 0.4);
  row.moveTo([0, -3.4, 0]);
  scene.add(row);
  costText = row; // treat the row as the tracked mobject
}

function updateScene() {
  dotA.moveTo(axes.c2p(minutes, costA(minutes)));
  dotB.moveTo(axes.c2p(minutes, costB(minutes)));
  stemA.setVertices([axes.c2p(minutes, 0), axes.c2p(minutes, costA(minutes))]);
  stemB.setVertices([axes.c2p(minutes, 0), axes.c2p(minutes, costB(minutes))]);
}

const controls = new Controls(scene, { position: 'bottom-left', width: 260 });
controls.addSlider({
  label: 'Minutes used',
  min: 0, max: 600, value: 100, step: 5,
  onChange: (val) => { minutes = val; updateScene(); updateReadout(); }
});
controls.addButton({
  label: 'Jump to break-even (300 min)',
  onClick: () => { minutes = 300; updateScene(); updateReadout(); }
});

// Make the break-even dot hoverable for a subtle highlight
makeHoverable(breakDot, scene, { hoverScale: 1.6, hoverColor: YELLOW });

await scene.wait(999999);"}

